Reads the elastic status file, the KV lazy owner's backing, and the"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        payload = collect()
        (D / f"{name}.json").write_text(json.dumps(payload))
        print(f"  saved {name}: " + ", ".join(
            f"{k}={v['prompt_tokens']} ({v['server_prompt_tokens']} server)"
            for k, v in payload.items()))
    elif cmd == "check":
        ref_name = sys.argv[2]
        cached = json.loads((D / f"{ref_name}.json").read_text())
        current = collect(cached)
        report = stats(cached, current)
        print_report(f"{ref_name} vs current", report)
    elif cmd == "compare":
        a_name, b_name = sys.argv[2], sys.argv[3]
        a = json.loads((D / f"{a_name}.json").read_text())
        b = json.loads((D / f"{b_name}.json").read_text())
        print_report(f"{b_name} vs {a_name}", stats(a, b))
    else:
        print(__doc__)
        sys.exit(1)


if __name__ == "__main__":
    main()


